import React, { useEffect, useState } from "react";
import { fetchReport, leadsAPI, getMyLandingPages } from "../";
import LPChart from "../components/LPChart";
import LeadTable from "../components/LeadTable";
import LeadStatusChart from "../components/LeadStatusChart";

const Report = ({ userId }) => {
  const [report, setReport] = useState(null);
  const [leads, setLeads] = useState([]);
  const [lps, setLps] = useState([]);
  const [filterLP, setFilterLP] = useState("all");
  const [filterDate, setFilterDate] = useState({ from: "", to: "" });

  useEffect(() => {
    const fetchData = async () => {
      const rep = await fetchReport(userId);
      setReport(rep);

      const leadRes = await leadsAPI.get(`?userId=${userId}`);
      setLeads(leadRes.data.data);

      const lpData = await getMyLandingPages(userId);
      setLps(lpData);
    };
    fetchData();
  }, [userId]);

  if (!report) return <div>Loading...</div>;

  // Filter leads theo LP & khoảng thời gian
  const filteredLeads = leads.filter(lead => {
    let matchLP = filterLP === "all" || lead.landingId === filterLP;
    let matchDate = true;
    if (filterDate.from) matchDate = new Date(lead.createdAt) >= new Date(filterDate.from);
    if (matchDate && filterDate.to) matchDate = new Date(lead.createdAt) <= new Date(filterDate.to);
    return matchLP && matchDate;
  });

  return (
    <div style={{ padding: "20px" }}>
      <h2>LandingHub Dashboard</h2>

      {/* Filter */}
      <div style={{ marginBottom: "20px", display: "flex", gap: "20px", flexWrap: "wrap" }}>
        <div>
          <label>Landing Page: </label>
          <select value={filterLP} onChange={e => setFilterLP(e.target.value)}>
            <option value="all">Tất cả</option>
            {lps.map(lp => <option key={lp._id} value={lp._id}>{lp.name}</option>)}
          </select>
        </div>
        <div>
          <label>Từ ngày: </label>
          <input type="date" value={filterDate.from} onChange={e => setFilterDate({...filterDate, from: e.target.value})} />
        </div>
        <div>
          <label>Đến ngày: </label>
          <input type="date" value={filterDate.to} onChange={e => setFilterDate({...filterDate, to: e.target.value})} />
        </div>
      </div>

      {/* KPIs */}
      <div style={{ display: "flex", gap: "20px", marginBottom: "20px" }}>
        <div><strong>Tổng Lead:</strong> {filteredLeads.length}</div>
        <div><strong>Tổng LP:</strong> {lps.length}</div>
      </div>

      {/* Charts */}
      <div style={{ display: "flex", flexWrap: "wrap", gap: "40px", marginBottom: "40px" }}>
        <LeadStatusChart leadStatus={report.leadStatus} />
        <LPChart lpStats={report.lpStats} />
      </div>

      {/* Lead Table */}
      <LeadTable leads={filteredLeads} />
    </div>
  );
};

export default Report;
